from ncclient.devices.default import DefaultDeviceHandler
from ncclient.xml_ import BASE_NS_1_0


def passthrough(xml):
    return xml


class RfswDeviceHandler(DefaultDeviceHandler):
    """
    Nokia RF SW handler for device specific information.
    """

    def __init__(self, device_params):
        super(RfswDeviceHandler, self).__init__(device_params)

    def get_capabilities(self):
        """Set RF SW device handler client capabilities

        Set additional capabilities beyond the default device handler.

        Returns:
            A list of strings representing NETCONF capabilities to be
            sent to the server.
        """
        capabilities = [
            "urn:ietf:params:netconf:base:1.1",
            "urn:ietf:params:netconf:capability:writable-running:1.0",
            "urn:ietf:params:netconf:capability:xpath:1.0",
            "urn:ietf:params:netconf:capability:notification:1.0",
            "urn:ietf:params:netconf:capability:interleave:1.0",
            "urn:ietf:params:netconf:capability:with-defaults:1.0",
        ]
        return capabilities

    def get_xml_base_namespace_dict(self):
        return {None: BASE_NS_1_0}

    def get_xml_extra_prefix_kwargs(self):
        d = {}
        d.update(self.get_xml_base_namespace_dict())
        return {"nsmap": d}

    def perform_qualify_check(self):
        return True

    def transform_reply(self):
        return passthrough
